//! Runtime for Rust generated by `n64rusty-translator`.
//!
//! Deliberately tiny and dependency-free: generated code depends only on this
//! crate, so edits to the translator, hooks or host do not rebuild it.
//!
//! It holds the guest CPU state ([`Ctx`]), big-endian guest RAM ([`Memory`])
//! and the single call dispatch point ([`Ctx::call`]) through which every
//! guest call goes, so any guest function can be overridden by address.

#![forbid(unsafe_code)]

use std::collections::{BTreeMap, HashMap};

mod fpu;
mod memory;

pub use fpu::{cvt_l, cvt_w, fcmp, Round};
pub use memory::{Flash, FlashOp, Io, Memory};

/// Crate version, checked against the version recorded in generated code.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

/// A recompiled (or host-written) guest function.
pub type GuestFn = fn(&mut Ctx);

/// Sign-extends a 32-bit result to a 64-bit register value, as the VR4300
/// does for every 32-bit operation.
#[inline(always)]
pub const fn sx32(v: u32) -> u64 {
    v as i32 as i64 as u64
}

/// Guest CPU state plus memory and the function table.
pub struct Ctx {
    /// General-purpose registers. `r[0]` is never written by generated code.
    pub r: [u64; 32],
    /// Multiply/divide result register HI.
    pub hi: u64,
    /// Multiply/divide result register LO.
    pub lo: u64,
    /// Floating-point registers, raw. See [`Ctx::fr`] for how singles and
    /// doubles map onto them.
    pub f: [u64; 32],
    /// Floating-point control/status register (FCR31): rounding mode in
    /// bits 0-1, compare condition in bit 23.
    pub fcr31: u32,
    /// The Status register's FR bit. `true`: 32 registers of 64 bits.
    /// `false`: MIPS II layout, where single `n` (odd) is the high half of
    /// `f[n - 1]` and doubles live in even registers. The console's boot
    /// code sets FR, so it defaults to `true`.
    pub fr: bool,
    /// Guest RAM.
    pub mem: Memory,
    funcs: HashMap<u32, GuestFn>,
    overrides: HashMap<u32, GuestFn>,
    overlays: Vec<Overlay>,
    /// Overlays currently in RAM, as indexes into `overlays`, each with the
    /// ranges later copies have overwritten since it was loaded.
    loaded: Vec<(usize, Vec<(u32, u32)>)>,
    /// Functions of code the game writes into RAM itself (unpacked or
    /// built, so no cartridge copy shows it), by address: each candidate's
    /// length in bytes, the [`code_hash`] of its words and the function.
    images: HashMap<u32, Vec<(u32, u64, GuestFn)>>,
    /// Image functions whose bytes matched RAM when last called, with their
    /// length; dropped when a copy or an I-cache invalidation covers them.
    /// shortcut: code the CPU rewrites with neither keeps running the old
    /// translation; hash on every call if a game ever does that.
    verified: BTreeMap<u32, (u32, GuestFn)>,
    /// The most recent call targets, oldest first once full; see
    /// [`Ctx::recent_calls`].
    trace: [u32; TRACE_LEN],
    /// The function being entered: what [`Ctx::last_call`] reports.
    entering: u32,
    /// Number of calls made through [`Ctx::call`].
    pub calls: u64,
    /// Current call depth.
    pub depth: u32,
    /// COP0 (system control) registers, as written by MTC0.
    pub cop0: [u32; 32],
    /// TLB entries as PageMask, EntryHi, EntryLo0, EntryLo1. Stored for
    /// TLBR and TLBP; addresses are not translated through them.
    pub tlb: [[u32; 4]; 32],
    /// Virtual time in COP0 Count ticks: advances by [`COUNT_PER_CALL`]
    /// per call, and hosts move it forward when the game waits.
    pub clock: u64,
    /// When `clock` reaches this, the next call first runs `on_deadline`.
    /// Hosts use it to deliver interrupts (retrace, timers) to a game that
    /// is busy and never blocks.
    pub deadline: u64,
    /// See [`Ctx::deadline`].
    pub on_deadline: Option<GuestFn>,
    /// Runs a call to code with no translation (an interpreter, say), given
    /// the address; without one such a call panics.
    pub on_missing: Option<fn(&mut Ctx, u32)>,
    /// Calls to addresses in this range go to `on_missing` even when a
    /// translation exists (except replaced routines): a debugging aid to
    /// compare translated code with an interpreter.
    pub interpret: Option<(u32, u32)>,
}

struct Overlay {
    rom: u32,
    ram: u32,
    len: u32,
    funcs: HashMap<u32, GuestFn>,
}

/// How far the virtual COP0 Count register advances per call.
pub const COUNT_PER_CALL: u32 = 64;

/// How many recent calls [`Ctx`] remembers for crash reports.
pub const TRACE_LEN: usize = 64;

impl Ctx {
    /// A context with zeroed registers and the given RAM.
    pub fn new(mem: Memory) -> Self {
        Self {
            r: [0; 32],
            hi: 0,
            lo: 0,
            f: [0; 32],
            fcr31: 0,
            fr: true,
            mem,
            funcs: HashMap::new(),
            overrides: HashMap::new(),
            overlays: Vec::new(),
            loaded: Vec::new(),
            images: HashMap::new(),
            verified: BTreeMap::new(),
            trace: [0; TRACE_LEN],
            entering: 0,
            calls: 0,
            depth: 0,
            cop0: [0; 32],
            tlb: [[0; 4]; 32],
            clock: 0,
            deadline: u64::MAX,
            on_deadline: None,
            on_missing: None,
            interpret: None,
        }
    }

    /// Registers a recompiled function at its guest address.
    pub fn register(&mut self, addr: u32, f: GuestFn) {
        self.funcs.insert(addr, f);
    }

    /// Replaces the function at `addr`. Overrides win over registered
    /// functions, so a hook can stand in for any guest routine.
    /// The override at `addr`, if any.
    pub fn override_at(&self, addr: u32) -> Option<GuestFn> {
        self.overrides.get(&addr).copied()
    }

    pub fn set_override(&mut self, addr: u32, f: GuestFn) {
        self.overrides.insert(addr, f);
    }

    /// Removes an override, restoring the registered function.
    pub fn clear_override(&mut self, addr: u32) {
        self.overrides.remove(&addr);
    }

    /// Registers the functions of code the game copies from the cartridge
    /// at run time: `len` bytes from ROM offset `rom` placed at `ram`.
    /// They are only called while that copy is in RAM (see
    /// [`Ctx::overlay_loaded`]), so overlays sharing an address range
    /// dispatch to whichever one is loaded.
    pub fn register_overlay(&mut self, rom: u32, ram: u32, len: u32, funcs: &[(u32, GuestFn)]) {
        self.overlays.push(Overlay {
            rom,
            ram,
            len,
            funcs: funcs.iter().copied().collect(),
        });
    }

    /// Registers a function of code the game writes into RAM itself: it runs
    /// at `addr` only while the `len` bytes there hash to `hash` (see
    /// [`code_hash`]), checked at the first call after they may have changed.
    pub fn register_image_fn(&mut self, addr: u32, len: u32, hash: u64, f: GuestFn) {
        self.images.entry(addr).or_default().push((len, hash, f));
    }

    /// The code in `len` bytes at `ram` may have changed (an I-cache
    /// invalidation, or a copy): image functions there are checked again.
    pub fn code_written(&mut self, ram: u32, len: u32) {
        // Image functions are shorter than this, so one starting before
        // `ram` by more cannot reach it.
        const LONGEST: u32 = 0x10_0000;
        // A bogus length must not wrap below `ram`.
        let end = ram.saturating_add(len);
        let hit: Vec<u32> = self
            .verified
            .range(ram.saturating_sub(LONGEST)..end)
            .filter(|(&a, &(n, _))| a.wrapping_add(n) > ram)
            .map(|(&a, _)| a)
            .collect();
        for a in hit {
            self.verified.remove(&a);
        }
    }

    /// The image function at `addr` whose bytes are in RAM now, if any.
    fn verify_image(&mut self, addr: u32) -> Option<GuestFn> {
        let cands = self.images.get(&addr)?;
        let bytes = self.mem.bytes();
        let at = (addr & 0x1FFF_FFFF) as usize;
        let &(len, _, f) = cands.iter().find(|&&(len, hash, _)| {
            bytes
                .get(at..at + len as usize)
                .is_some_and(|b| code_hash(b) == hash)
        })?;
        self.verified.insert(addr, (len, f));
        Some(f)
    }

    /// Records that `len` bytes from ROM offset `rom` were copied to `ram`.
    /// An overlay that starts at exactly this copy is loaded. A copy over
    /// part of a loaded overlay (often data into its own data area) makes
    /// only the functions it covers unavailable; one over all of it
    /// unloads it.
    pub fn overlay_loaded(&mut self, rom: u32, ram: u32, len: u32) {
        self.code_written(ram, len);
        let (lo, hi) = (ram, ram.wrapping_add(len));
        let ovl = &self.overlays;
        self.loaded.retain_mut(|(i, dead)| {
            let o = &ovl[*i];
            let (olo, ohi) = (o.ram, o.ram.wrapping_add(o.len));
            if ohi <= lo || olo >= hi {
                return true;
            }
            if lo <= olo && hi >= ohi {
                return false;
            }
            add_range(dead, lo, hi);
            true
        });
        for (i, o) in self.overlays.iter().enumerate() {
            if o.rom == rom && o.ram == ram {
                self.loaded.push((i, Vec::new()));
            }
        }
    }

    /// For a crash report: the overlays whose RAM range holds `addr`, and
    /// whether each one is loaded or hidden there by a later copy.
    fn overlays_at(&self, addr: u32) -> String {
        let mut s = String::new();
        for (i, o) in self.overlays.iter().enumerate() {
            if addr < o.ram || addr >= o.ram.wrapping_add(o.len) {
                continue;
            }
            let state = match self.loaded.iter().find(|(j, _)| *j == i) {
                None => "not loaded".to_string(),
                Some((_, dead)) => match dead.iter().find(|&&(lo, hi)| addr >= lo && addr < hi) {
                    Some((lo, hi)) => format!("loaded, but {lo:#010x}..{hi:#010x} was copied over"),
                    None => "loaded".to_string(),
                },
            };
            let has = if o.funcs.contains_key(&addr) {
                "has it"
            } else {
                "lacks it"
            };
            s.push_str(&format!(
                "\n  overlay rom {:#x} -> {:#010x} len {:#x}: {state}, {has}",
                o.rom, o.ram, o.len
            ));
        }
        s
    }

    /// The function at `addr`: an override, a loaded overlay's, or a
    /// registered one.
    fn lookup(&self, addr: u32) -> Option<GuestFn> {
        match self.overrides.get(&addr) {
            Some(f) => Some(*f),
            None => self.lookup_game(addr),
        }
    }

    /// The function at `addr` as the game has it: overrides skipped.
    fn lookup_game(&self, addr: u32) -> Option<GuestFn> {
        for (i, dead) in self.loaded.iter().rev() {
            if dead.iter().any(|&(lo, hi)| addr >= lo && addr < hi) {
                continue;
            }
            if let Some(f) = self.overlays[*i].funcs.get(&addr) {
                return Some(*f);
            }
        }
        if let Some(&(_, f)) = self.verified.get(&addr) {
            return Some(f);
        }
        self.funcs.get(&addr).copied()
    }

    /// Calls the guest function at `addr`. Every call in generated code goes
    /// through here.
    pub fn call(&mut self, addr: u32) {
        self.call_as(addr, true);
    }

    /// Calls the game's own function at `addr`, skipping an override there,
    /// so an override can wrap the function it replaces.
    pub fn call_original(&mut self, addr: u32) {
        self.call_as(addr, false);
    }

    fn call_as(&mut self, addr: u32, overrides: bool) {
        let overridden = overrides && self.overrides.contains_key(&addr);
        let forced = self
            .interpret
            .is_some_and(|(lo, hi)| (lo..hi).contains(&addr) && !overridden);
        let f = if forced {
            None
        } else if overridden {
            self.overrides.get(&addr).copied()
        } else {
            self.lookup_game(addr).or_else(|| self.verify_image(addr))
        };
        self.tick(addr);
        // Set after the tick: a deadline handler it runs makes calls too.
        self.entering = addr;
        match f {
            Some(f) => {
                self.depth += 1;
                f(self);
                self.depth -= 1;
            }
            None if self.on_missing.is_some() => {
                let run = self.on_missing.unwrap();
                self.depth += 1;
                run(self, addr);
                self.depth -= 1;
            }
            None => panic!(
                "call to unknown guest function {addr:#010x}{}{}",
                memory::wild_hint(addr),
                self.overlays_at(addr)
            ),
        }
    }

    /// The function [`Ctx::call`] last entered: read on entry, it lets one
    /// override serve many addresses. Calls made after that (and ticks an
    /// interpreter counts itself) change it, so read it first.
    pub fn last_call(&self) -> u32 {
        self.entering
    }

    /// What every call costs: it goes in the trace and moves the clock, and
    /// a due deadline runs its handler. An interpreter calls this for the
    /// calls it makes itself, so time moves as in translated code.
    pub fn tick(&mut self, addr: u32) {
        self.trace[(self.calls % TRACE_LEN as u64) as usize] = addr;
        self.calls += 1;
        self.clock = self.clock.wrapping_add(u64::from(COUNT_PER_CALL));
        if self.clock >= self.deadline {
            if let Some(h) = self.on_deadline {
                self.deadline = u64::MAX;
                h(self);
            }
        }
    }

    /// MFC0. Count (register 9) reads [`Ctx::clock`], so runs are
    /// reproducible.
    pub fn mfc0(&self, n: usize) -> u64 {
        match n {
            9 => sx32(self.clock as u32),
            _ => sx32(self.cop0[n]),
        }
    }

    /// MTC0. Writes are stored; none of them has a side effect yet.
    pub fn mtc0(&mut self, n: usize, v: u64) {
        self.cop0[n] = v as u32;
    }

    /// TLBR (1), TLBWI (2), TLBWR (6) and TLBP (8), on COP0 Index (0),
    /// EntryLo0/1 (2, 3), PageMask (5) and EntryHi (10).
    pub fn tlb(&mut self, funct: u32) {
        const REGS: [usize; 4] = [5, 10, 2, 3];
        let index = (self.cop0[0] & 31) as usize;
        match funct {
            1 => {
                for (k, &n) in REGS.iter().enumerate() {
                    self.cop0[n] = self.tlb[index][k];
                }
            }
            2 | 6 => {
                // Random lies between Wired and 31, so slot 31 is always one it could pick.
                let slot = if funct == 2 { index } else { 31 };
                for (k, &n) in REGS.iter().enumerate() {
                    self.tlb[slot][k] = self.cop0[n];
                }
            }
            8 => {
                let hi = self.cop0[10];
                let hit = self.tlb.iter().position(|e| {
                    let mask = !(e[0] | 0x1FFF);
                    let global = e[2] & e[3] & 1 != 0;
                    (e[1] ^ hi) & mask == 0 && (global || (e[1] ^ hi) & 0xFF == 0)
                });
                self.cop0[0] = hit.map_or(0x8000_0000, |k| k as u32);
            }
            _ => self.unimplemented(0, funct),
        }
    }

    /// Whether a function is registered or overridden at `addr`.
    pub fn has_function(&self, addr: u32) -> bool {
        self.lookup(addr).is_some()
    }

    /// Whether a call to `addr` would run translated code: a registered or
    /// overridden function, or a saved-image function whose bytes are in RAM
    /// now (checking it, as a call would).
    pub fn has_translation(&mut self, addr: u32) -> bool {
        self.lookup(addr).is_some() || self.verify_image(addr).is_some()
    }

    /// The most recent call targets, oldest first.
    pub fn recent_calls(&self) -> Vec<u32> {
        let n = self.calls.min(TRACE_LEN as u64) as usize;
        let start = self.calls as usize - n;
        (start..start + n)
            .map(|k| self.trace[k % TRACE_LEN])
            .collect()
    }

    /// Signed 32-bit divide (DIV). Division by zero and overflow give the
    /// VR4300's results instead of trapping.
    pub fn div(&mut self, a: u64, b: u64) {
        let n = a as i32;
        let d = b as i32;
        if d == 0 {
            self.lo = if n < 0 { 1 } else { u64::MAX };
            self.hi = sx32(n as u32);
        } else {
            self.lo = sx32(n.wrapping_div(d) as u32);
            self.hi = sx32(n.wrapping_rem(d) as u32);
        }
    }

    /// Unsigned 32-bit divide (DIVU).
    pub fn divu(&mut self, a: u64, b: u64) {
        let n = a as u32;
        let d = b as u32;
        match (n.checked_div(d), n.checked_rem(d)) {
            (Some(q), Some(r)) => {
                self.lo = sx32(q);
                self.hi = sx32(r);
            }
            _ => {
                self.lo = u64::MAX;
                self.hi = sx32(n);
            }
        }
    }

    /// Signed 64-bit divide (DDIV).
    pub fn ddiv(&mut self, a: u64, b: u64) {
        let n = a as i64;
        let d = b as i64;
        if d == 0 {
            self.lo = if n < 0 { 1 } else { u64::MAX };
            self.hi = n as u64;
        } else {
            self.lo = n.wrapping_div(d) as u64;
            self.hi = n.wrapping_rem(d) as u64;
        }
    }

    /// Unsigned 64-bit divide (DDIVU).
    pub fn ddivu(&mut self, a: u64, b: u64) {
        match (a.checked_div(b), a.checked_rem(b)) {
            (Some(q), Some(r)) => {
                self.lo = q;
                self.hi = r;
            }
            _ => {
                self.lo = u64::MAX;
                self.hi = a;
            }
        }
    }

    /// Signed 32-bit multiply (MULT).
    pub fn mult(&mut self, a: u64, b: u64) {
        let p = (a as i32 as i64).wrapping_mul(b as i32 as i64) as u64;
        self.lo = sx32(p as u32);
        self.hi = sx32((p >> 32) as u32);
    }

    /// Unsigned 32-bit multiply (MULTU).
    pub fn multu(&mut self, a: u64, b: u64) {
        let p = (a as u32 as u64) * (b as u32 as u64);
        self.lo = sx32(p as u32);
        self.hi = sx32((p >> 32) as u32);
    }

    /// Signed 64-bit multiply (DMULT).
    pub fn dmult(&mut self, a: u64, b: u64) {
        let p = (a as i64 as i128).wrapping_mul(b as i64 as i128) as u128;
        self.lo = p as u64;
        self.hi = (p >> 64) as u64;
    }

    /// Unsigned 64-bit multiply (DMULTU).
    pub fn dmultu(&mut self, a: u64, b: u64) {
        let p = (a as u128) * (b as u128);
        self.lo = p as u64;
        self.hi = (p >> 64) as u64;
    }

    /// Called by generated code for an instruction the translator does not
    /// support yet.
    #[cold]
    pub fn unimplemented(&mut self, pc: u32, word: u32) -> ! {
        panic!("unimplemented instruction {word:#010x} at {pc:#010x}")
    }
}

/// FNV-1a over code bytes: how image functions are matched against RAM.
pub fn code_hash(bytes: &[u8]) -> u64 {
    bytes.iter().fold(0xCBF2_9CE4_8422_2325, |h, &b| {
        (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01B3)
    })
}

/// Called by generated code when execution reaches an address inside a
/// function that is not a known block start (for example a jump table target
/// that was not discovered).
#[cold]
pub fn bad_pc(func: u32, pc: u32) -> ! {
    panic!("jump to {pc:#010x} inside function {func:#010x} is not a known block start")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn deadline_runs_hook_once_before_the_call() {
        fn hook(c: &mut Ctx) {
            c.r[2] += 1;
        }
        fn callee(c: &mut Ctx) {
            c.r[3] = c.r[2];
        }
        let mut c = Ctx::new(Memory::new(16));
        c.register(0x8000_1000, callee);
        c.on_deadline = Some(hook);
        c.deadline = u64::from(COUNT_PER_CALL) * 2;
        c.call(0x8000_1000);
        assert_eq!((c.r[2], c.r[3]), (0, 0));
        c.call(0x8000_1000);
        assert_eq!((c.r[2], c.r[3]), (1, 1));
        // Disarmed until the host sets a new deadline.
        c.call(0x8000_1000);
        assert_eq!(c.r[2], 1);
    }

    #[test]
    fn version_is_set() {
        assert!(!VERSION.is_empty());
    }

    #[test]
    fn div_edge_cases() {
        let mut c = Ctx::new(Memory::new(16));
        c.div(7, 0);
        assert_eq!((c.lo, c.hi), (u64::MAX, 7));
        c.div(sx32(-7i32 as u32), 0);
        assert_eq!((c.lo, c.hi), (1, sx32(-7i32 as u32)));
        c.div(sx32(i32::MIN as u32), sx32(-1i32 as u32));
        assert_eq!((c.lo, c.hi), (sx32(i32::MIN as u32), 0));
        c.div(sx32(-7i32 as u32), 2);
        assert_eq!((c.lo, c.hi), (sx32(-3i32 as u32), sx32(-1i32 as u32)));
        c.divu(0xFFFF_FFFF, 0);
        assert_eq!((c.lo, c.hi), (u64::MAX, u64::MAX));
        c.ddiv(i64::MIN as u64, u64::MAX);
        assert_eq!((c.lo, c.hi), (i64::MIN as u64, 0));
    }

    #[test]
    fn mult_splits_and_sign_extends() {
        let mut c = Ctx::new(Memory::new(16));
        c.multu(0xFFFF_FFFF, 0xFFFF_FFFF);
        assert_eq!(c.lo, 1);
        assert_eq!(c.hi, sx32(0xFFFF_FFFE));
        c.mult(sx32(-2i32 as u32), 3);
        assert_eq!((c.lo, c.hi), (sx32(-6i32 as u32), u64::MAX));
        c.dmultu(u64::MAX, 2);
        assert_eq!((c.lo, c.hi), (u64::MAX - 1, 1));
    }

    #[test]
    fn overlays_dispatch_by_what_is_loaded() {
        fn a(c: &mut Ctx) {
            c.r[2] = 0xA;
        }
        fn b(c: &mut Ctx) {
            c.r[2] = 0xB;
        }
        let mut c = Ctx::new(Memory::new(16));
        c.register_overlay(0x1000, 0x8010_0000, 0x100, &[(0x8010_0000, a)]);
        c.register_overlay(0x2000, 0x8010_0000, 0x200, &[(0x8010_0000, b)]);
        assert!(!c.has_function(0x8010_0000));
        c.overlay_loaded(0x1000, 0x8010_0000, 0x100);
        c.call(0x8010_0000);
        assert_eq!(c.r[2], 0xA);
        c.overlay_loaded(0x2000, 0x8010_0000, 0x200);
        c.call(0x8010_0000);
        assert_eq!(c.r[2], 0xB);
        // Data copied into part of it hides only what it covers.
        c.overlay_loaded(0x9000, 0x8010_0080, 0x10);
        assert!(c.has_function(0x8010_0000));
        c.overlay_loaded(0x9000, 0x8010_0000, 0x10);
        assert!(!c.has_function(0x8010_0000));
        // Reloading brings it back; a copy over all of it unloads it.
        c.overlay_loaded(0x1000, 0x8010_0000, 0x100);
        assert!(c.has_function(0x8010_0000));
        c.overlay_loaded(0x9000, 0x800F_0000, 0x10_0000);
        assert!(!c.has_function(0x8010_0000));
    }

    #[test]
    fn image_functions_run_only_while_their_bytes_are_in_ram() {
        fn a(c: &mut Ctx) {
            c.r[2] = 0xA;
        }
        fn b(c: &mut Ctx) {
            c.r[2] = 0xB;
        }
        let mut c = Ctx::new(Memory::new(0x100));
        let (code_a, code_b) = ([1u8, 2, 3, 4], [5u8, 6, 7, 8]);
        c.register_image_fn(0x8000_0010, 4, code_hash(&code_a), a);
        c.register_image_fn(0x8000_0010, 4, code_hash(&code_b), b);
        c.mem.bytes_mut()[0x10..0x14].copy_from_slice(&code_a);
        c.call(0x8000_0010);
        assert_eq!(c.r[2], 0xA);
        // New code written there is picked up after an invalidation.
        c.mem.bytes_mut()[0x10..0x14].copy_from_slice(&code_b);
        c.code_written(0x8000_0000, 0x20);
        c.call(0x8000_0010);
        assert_eq!(c.r[2], 0xB);
        c.mem.bytes_mut()[0x10..0x14].copy_from_slice(&[0; 4]);
        c.code_written(0x8000_0012, 1);
        assert!(
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| c.call(0x8000_0010))).is_err()
        );
    }

    #[test]
    fn an_override_can_wrap_the_function_it_replaces() {
        fn game(c: &mut Ctx) {
            c.r[2] += 1;
        }
        fn wrap(c: &mut Ctx) {
            c.r[2] += 10;
            c.call_original(0x8000_0400);
            c.r[2] += 100;
        }
        let mut c = Ctx::new(Memory::new(16));
        c.register(0x8000_0400, game);
        c.set_override(0x8000_0400, wrap);
        c.call(0x8000_0400);
        assert_eq!(c.r[2], 111);
    }

    #[test]
    fn unknown_call_names_the_overlays_there() {
        fn a(_: &mut Ctx) {}
        let mut c = Ctx::new(Memory::new(16));
        c.register_overlay(0x1000, 0x8010_0000, 0x100, &[(0x8010_0000, a)]);
        c.overlay_loaded(0x1000, 0x8010_0000, 0x100);
        assert_eq!(
            c.overlays_at(0x8010_0040),
            "\n  overlay rom 0x1000 -> 0x80100000 len 0x100: loaded, lacks it"
        );
        c.overlay_loaded(0x9000, 0x8010_0000, 0x10);
        assert!(c
            .overlays_at(0x8010_0000)
            .contains("was copied over, has it"));
    }

    #[test]
    fn overrides_win() {
        fn a(c: &mut Ctx) {
            c.r[2] = 1;
        }
        fn b(c: &mut Ctx) {
            c.r[2] = 2;
        }
        let mut c = Ctx::new(Memory::new(16));
        c.register(0x8000_0400, a);
        c.call(0x8000_0400);
        assert_eq!(c.r[2], 1);
        c.set_override(0x8000_0400, b);
        c.call(0x8000_0400);
        assert_eq!(c.r[2], 2);
        c.clear_override(0x8000_0400);
        c.call(0x8000_0400);
        assert_eq!(c.r[2], 1);
    }

    #[test]
    fn last_call_names_the_function_entered_past_a_deadline() {
        fn other(_: &mut Ctx) {}
        fn handler(c: &mut Ctx) {
            c.call(0x8000_0500);
        }
        fn hook(c: &mut Ctx) {
            c.r[2] = u64::from(c.last_call());
        }
        let mut c = Ctx::new(Memory::new(16));
        c.register(0x8000_0500, other);
        c.set_override(0x8000_0400, hook);
        c.on_deadline = Some(handler);
        c.deadline = 0;
        c.call(0x8000_0400);
        assert_eq!(c.r[2], 0x8000_0400);
    }
}

/// Adds `lo..hi` to the disjoint `ranges`, merging what it touches. Games
/// copy into the same buffers over and over; unmerged, every call would
/// look through each of those copies.
fn add_range(ranges: &mut Vec<(u32, u32)>, lo: u32, hi: u32) {
    let (mut lo, mut hi) = (lo, hi);
    ranges.retain(|&(a, b)| {
        let touches = a <= hi && b >= lo;
        if touches {
            lo = lo.min(a);
            hi = hi.max(b);
        }
        !touches
    });
    ranges.push((lo, hi));
}

#[cfg(test)]
mod range_tests {
    use super::add_range;

    #[test]
    fn repeated_and_touching_copies_merge() {
        let mut r = Vec::new();
        for _ in 0..1000 {
            add_range(&mut r, 0x100, 0x200);
        }
        add_range(&mut r, 0x400, 0x500);
        assert_eq!(r, [(0x100, 0x200), (0x400, 0x500)]);
        add_range(&mut r, 0x200, 0x400);
        assert_eq!(r, [(0x100, 0x500)]);
    }
}

#[cfg(test)]
mod interpret_tests {
    use super::{Ctx, Memory};

    fn translated(c: &mut Ctx) {
        c.r[2] = 1;
    }

    fn interpreter(c: &mut Ctx, _: u32) {
        c.r[2] = 2;
    }

    #[test]
    fn interpret_range_sends_translated_calls_to_the_interpreter() {
        let mut c = Ctx::new(Memory::new(0x1000));
        c.register(0x8000_0100, translated);
        c.register(0x8000_0200, translated);
        c.on_missing = Some(interpreter);
        c.interpret = Some((0x8000_0100, 0x8000_0200));
        c.call(0x8000_0100);
        assert_eq!(c.r[2], 2);
        c.call(0x8000_0200);
        assert_eq!(c.r[2], 1, "the range's end is outside it");
    }
}
